def chunk(items, size):
    if not items or size <= 0:
        return []
    result = []
    current_chunk = []
    for i in range(len(items) - size + 1):
        current_chunk.append(items[i:i + size])
        if i == len(items) - size:
            result.append(current_chunk)
            current_chunk = []
    if current_chunk:
        result.append(current_chunk)
    return result or []
